using System;
using System.Collections.Generic;
using UnityEngine;

namespace RTXMnesia.Sound
{
    /// <summary>
    /// The game's sounds: every .ogg / .wav of sounds/, music/ and the language folder as an AudioClip, found by
    /// file name like cSoundManager::CreateSoundData (name without extension, any case, first file in
    /// resources.cfg order), and every sound entity file (.snt, cSoundEntityData) by name.
    /// Generated by SoundConverter into Assets/AmnesiaImported/Sounds (game data, never in git).
    /// </summary>
    public class HplSoundBank : ScriptableObject
    {
        [Serializable]
        public struct Clip
        {
            [Tooltip("File name without extension, lower case.")]
            public string name;
            [Tooltip("Path relative to the game folder, lower case, without extension.")]
            public string path;
            public AudioClip clip;
        }

        /// <summary>cSoundEntityData: the sounds of a .snt and its PROPERTIES.</summary>
        [Serializable]
        public class SoundEntityData
        {
            [Tooltip("File name without extension, lower case.")]
            public string name;
            [Tooltip("Path relative to the game folder, lower case, without extension.")]
            public string path;
            public string[] main = Array.Empty<string>(), start = Array.Empty<string>(), stop = Array.Empty<string>();
            public bool use3D = true, loop = true, stream = true, blockable, fadeStart = true, fadeStop = true;
            public float blockVolumeMul = 0.6f, volume = 1f, minDistance = 1f, maxDistance = 1f, random = 1f, interval;
            public int priority;

            [NonSerialized] readonly int[] _previous = { -1, -1, -1 };

            public string[] Sounds(SoundEntityType type) => type switch
            {
                SoundEntityType.Start => start,
                SoundEntityType.Stop => stop,
                _ => main,
            };

            public bool HasSound(SoundEntityType type) => Sounds(type).Length > 0;

            /// <summary>
            /// cSoundEntityData::GetRandomSoundName, with its quirk: skipping the previous sound only works when the
            /// previous index is above 0.
            /// </summary>
            public string GetRandomSoundName(SoundEntityType type, bool skipPrevious)
            {
                var names = Sounds(type);
                if (names.Length == 0) return "";
                int size = names.Length;
                if (size == 1) return names[0];

                int start = -1, sizeAdd = -1;
                int previous = _previous[(int)type];
                if (skipPrevious && size > 2 && previous < size && previous > 0)
                {
                    start = previous;
                    sizeAdd = start - 1;
                }
                int rand = Hpl.HplMath.RandRectl(start + 1, size + sizeAdd);
                if (rand >= size) rand -= size;
                _previous[(int)type] = rand;
                return names[rand];
            }
        }

        public List<Clip> clips = new();
        public List<SoundEntityData> soundEntities = new();

        Hpl.HplNameIndex<AudioClip> _clips;
        Hpl.HplNameIndex<SoundEntityData> _entities;

        /// <summary>cSoundManager::CreateSoundData: a sound file by name (extension optional, folders choose).</summary>
        public AudioClip GetClip(string file)
        {
            if (_clips == null)
            {
                _clips = new Hpl.HplNameIndex<AudioClip>();
                foreach (var c in clips) if (c.clip != null) _clips.Add(c.name, c.path, c.clip);
            }
            return _clips.Find(file);
        }

        /// <summary>cSoundEntityManager::CreateSoundEntity: a .snt by name (extension optional, folders choose).</summary>
        public SoundEntityData GetSoundEntity(string file)
        {
            if (_entities == null)
            {
                _entities = new Hpl.HplNameIndex<SoundEntityData>();
                foreach (var e in soundEntities) _entities.Add(e.name, e.path, e);
            }
            return _entities.Find(file);
        }
    }

    public enum SoundEntityType { Main, Start, Stop }

    /// <summary>eSoundEntryType: world sounds and GUI sounds have separate global volume and speed.</summary>
    [Flags]
    public enum SoundEntryType { World = 1, Gui = 2, All = ~0 }
}
